/**
 * Example Test File - Jest ESM with Mock Helpers
 *
 * This file demonstrates how to write tests using the new Jest ESM configuration
 * with mock helpers. Use this as a reference for migrating existing tests.
 */

import { jest, describe, it, expect, beforeEach, beforeAll } from '@jest/globals';
import request from 'supertest';
import express, { Express } from 'express';

// Import mock helpers
import {
  createMockFunction,
  createMockPrismaClient,
  createMockRedisClient,
  createMockRequest,
  createMockResponse,
  createMockNext,
  createMockUser,
  mockResolvedValue,
  mockRejectedValue,
  mockReturnValue,
} from '../helpers/mock-helpers.js';

// ============================================================================
// STEP 1: Define mocks BEFORE importing modules
// ============================================================================

// Create mock functions
const mockFindUser = jest.fn();
const mockCreateUser = jest.fn();
const mockUpdateUser = jest.fn();
const mockDeleteUser = jest.fn();

// Create mock Prisma client
const mockPrisma = createMockPrismaClient();

// Create mock Redis client
const mockRedis = createMockRedisClient();

// ============================================================================
// STEP 2: Configure jest.mock() BEFORE imports
// ============================================================================

// Mock the user service
jest.mock('../../services/members/user/user.service.js', () => ({
  findUser: mockFindUser,
  createUser: mockCreateUser,
  updateUser: mockUpdateUser,
  deleteUser: mockDeleteUser,
}));

// Mock Prisma client
jest.mock('../../db/prisma.client.js', () => ({
  prisma: mockPrisma,
  checkDatabaseConnection: jest.fn(),
}));

// Mock Redis client
jest.mock('../../db/redis.client.js', () => ({
  getRedisClient: jest.fn(() => mockRedis),
  redisHealthCheck: jest.fn(),
  isRedisReady: jest.fn(),
}));

// ============================================================================
// STEP 3: Import modules AFTER mocks are configured
// ============================================================================

import {
  findUser,
  createUser,
  updateUser,
  deleteUser,
} from '../../services/members/user/user.service.js';

import { prisma, checkDatabaseConnection } from '../../db/prisma.client.js';
import {
  getRedisClient,
  redisHealthCheck,
  isRedisReady,
} from '../../db/redis.client.js';

// ============================================================================
// TESTS
// ============================================================================

describe('Example Test Suite - Mock Helpers Usage', () => {
  // ============================================================================
  // Example 1: Testing async functions with mocks
  // ============================================================================

  describe('User Service Tests', () => {
    beforeEach(() => {
      jest.clearAllMocks();
    });

    it('should find user by id', async () => {
      // Arrange
      const mockUser = createMockUser({ id: '123', email: 'test@example.com' });
      mockResolvedValue(mockFindUser, mockUser);

      // Act
      const result = await findUser('123');

      // Assert
      expect(result).toEqual(mockUser);
      expect(mockFindUser).toHaveBeenCalledWith('123');
      expect(mockFindUser).toHaveBeenCalledTimes(1);
    });

    it('should return null when user not found', async () => {
      // Arrange
      mockResolvedValue(mockFindUser, null);

      // Act
      const result = await findUser('999');

      // Assert
      expect(result).toBeNull();
      expect(mockFindUser).toHaveBeenCalledWith('999');
    });

    it('should handle errors when finding user', async () => {
      // Arrange
      const error = new Error('Database connection failed');
      mockRejectedValue(mockFindUser, error);

      // Act & Assert
      await expect(findUser('123')).rejects.toThrow('Database connection failed');
      expect(mockFindUser).toHaveBeenCalledWith('123');
    });

    it('should create new user', async () => {
      // Arrange
      const userData = {
        email: 'new@example.com',
        firstName: 'New',
        lastName: 'User',
      };
      const createdUser = createMockUser(userData);
      mockResolvedValue(mockCreateUser, createdUser);

      // Act
      const result = await createUser(userData);

      // Assert
      expect(result).toEqual(createdUser);
      expect(mockCreateUser).toHaveBeenCalledWith(userData);
      expect(result.email).toBe('new@example.com');
    });

    it('should update user', async () => {
      // Arrange
      const updates = { firstName: 'Updated' };
      const updatedUser = createMockUser({ id: '123', firstName: 'Updated' });
      mockResolvedValue(mockUpdateUser, updatedUser);

      // Act
      const result = await updateUser('123', updates);

      // Assert
      expect(result).toEqual(updatedUser);
      expect(mockUpdateUser).toHaveBeenCalledWith('123', updates);
      expect(result.firstName).toBe('Updated');
    });

    it('should delete user', async () => {
      // Arrange
      mockResolvedValue(mockDeleteUser, true);

      // Act
      const result = await deleteUser('123');

      // Assert
      expect(result).toBe(true);
      expect(mockDeleteUser).toHaveBeenCalledWith('123');
    });
  });

  // ============================================================================
  // Example 2: Testing with Prisma client
  // ============================================================================

  describe('Prisma Client Tests', () => {
    beforeEach(() => {
      jest.clearAllMocks();
    });

    it('should query user from database', async () => {
      // Arrange
      const mockUser = createMockUser({ id: '123' });
      mockPrisma.user.findUnique.mockResolvedValue(mockUser);

      // Act
      const result = await prisma.user.findUnique({ where: { id: '123' } });

      // Assert
      expect(result).toEqual(mockUser);
      expect(mockPrisma.user.findUnique).toHaveBeenCalledWith({ where: { id: '123' } });
    });

    it('should check database connection', async () => {
      // Arrange
      (checkDatabaseConnection as jest.Mock).mockResolvedValue(true);

      // Act
      const result = await checkDatabaseConnection();

      // Assert
      expect(result).toBe(true);
      expect(checkDatabaseConnection).toHaveBeenCalled();
    });

    it('should create user in database', async () => {
      // Arrange
      const userData = { email: 'new@example.com', firstName: 'New', lastName: 'User' };
      const createdUser = createMockUser(userData);
      mockPrisma.user.create.mockResolvedValue(createdUser);

      // Act
      const result = await prisma.user.create({ data: userData });

      // Assert
      expect(result).toEqual(createdUser);
      expect(mockPrisma.user.create).toHaveBeenCalledWith({ data: userData });
    });

    it('should count users', async () => {
      // Arrange
      mockPrisma.user.count.mockResolvedValue(42);

      // Act
      const result = await prisma.user.count();

      // Assert
      expect(result).toBe(42);
      expect(mockPrisma.user.count).toHaveBeenCalled();
    });
  });

  // ============================================================================
  // Example 3: Testing with Redis client
  // ============================================================================

  describe('Redis Client Tests', () => {
    beforeEach(() => {
      jest.clearAllMocks();
    });

    it('should get data from cache', async () => {
      // Arrange
      const cachedData = JSON.stringify({ userId: '123', name: 'Cached User' });
      mockRedis.get.mockResolvedValue(cachedData);

      // Act
      const redis = getRedisClient();
      const result = await redis.get('user:123');

      // Assert
      expect(result).toBe(cachedData);
      expect(mockRedis.get).toHaveBeenCalledWith('user:123');
    });

    it('should set data in cache', async () => {
      // Arrange
      mockRedis.set.mockResolvedValue('OK');

      // Act
      const redis = getRedisClient();
      const result = await redis.set('user:123', JSON.stringify({ name: 'User' }));

      // Assert
      expect(result).toBe('OK');
      expect(mockRedis.set).toHaveBeenCalled();
    });

    it('should check Redis health', async () => {
      // Arrange
      const healthStatus = { status: 'healthy', latency: 5 };
      (redisHealthCheck as jest.Mock).mockResolvedValue(healthStatus);

      // Act
      const result = await redisHealthCheck();

      // Assert
      expect(result).toEqual(healthStatus);
      expect(result.status).toBe('healthy');
      expect(redisHealthCheck).toHaveBeenCalled();
    });

    it('should check if Redis is ready', async () => {
      // Arrange
      (isRedisReady as jest.Mock).mockResolvedValue(true);

      // Act
      const result = await isRedisReady();

      // Assert
      expect(result).toBe(true);
      expect(isRedisReady).toHaveBeenCalled();
    });
  });

  // ============================================================================
  // Example 4: Testing Express middleware
  // ============================================================================

  describe('Express Middleware Tests', () => {
    it('should use mock request/response/next', () => {
      // Arrange
      const req = createMockRequest({
        params: { id: '123' },
        body: { name: 'Test' },
        headers: { authorization: 'Bearer token' },
      });
      const res = createMockResponse();
      const next = createMockNext();

      // Act - Example middleware function
      const exampleMiddleware = (req: any, res: any, next: any) => {
        if (req.headers.authorization) {
          req.user = { id: '123' };
          next();
        } else {
          res.status(401).json({ error: 'Unauthorized' });
        }
      };

      exampleMiddleware(req, res, next);

      // Assert
      expect(req.user).toEqual({ id: '123' });
      expect(next).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalled();
    });

    it('should return 401 when no authorization header', () => {
      // Arrange
      const req = createMockRequest({ headers: {} });
      const res = createMockResponse();
      const next = createMockNext();

      // Act
      const exampleMiddleware = (req: any, res: any, next: any) => {
        if (req.headers.authorization) {
          next();
        } else {
          res.status(401).json({ error: 'Unauthorized' });
        }
      };

      exampleMiddleware(req, res, next);

      // Assert
      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ error: 'Unauthorized' });
      expect(next).not.toHaveBeenCalled();
    });
  });

  // ============================================================================
  // Example 5: Testing Express routes with supertest
  // ============================================================================

  describe('Express Routes with Supertest', () => {
    let app: Express;

    beforeAll(() => {
      // Create Express app
      app = express();
      app.use(express.json());

      // Define test routes
      app.get('/users/:id', async (req, res) => {
        try {
          const user = await findUser(req.params.id);
          if (!user) {
            return res.status(404).json({ error: 'User not found' });
          }
          res.json(user);
        } catch (error) {
          res.status(500).json({ error: 'Internal server error' });
        }
      });

      app.post('/users', async (req, res) => {
        try {
          const user = await createUser(req.body);
          res.status(201).json(user);
        } catch (error) {
          res.status(500).json({ error: 'Internal server error' });
        }
      });
    });

    beforeEach(() => {
      jest.clearAllMocks();
    });

    it('should return user by id', async () => {
      // Arrange
      const mockUser = createMockUser({ id: '123' });
      mockResolvedValue(mockFindUser, mockUser);

      // Act
      const response = await request(app).get('/users/123');

      // Assert
      expect(response.status).toBe(200);
      expect(response.body).toEqual(mockUser);
      expect(mockFindUser).toHaveBeenCalledWith('123');
    });

    it('should return 404 when user not found', async () => {
      // Arrange
      mockResolvedValue(mockFindUser, null);

      // Act
      const response = await request(app).get('/users/999');

      // Assert
      expect(response.status).toBe(404);
      expect(response.body).toEqual({ error: 'User not found' });
    });

    it('should create new user', async () => {
      // Arrange
      const userData = { email: 'new@example.com', firstName: 'New', lastName: 'User' };
      const createdUser = createMockUser(userData);
      mockResolvedValue(mockCreateUser, createdUser);

      // Act
      const response = await request(app).post('/users').send(userData);

      // Assert
      expect(response.status).toBe(201);
      expect(response.body).toEqual(createdUser);
      expect(mockCreateUser).toHaveBeenCalledWith(userData);
    });

    it('should handle errors gracefully', async () => {
      // Arrange
      const error = new Error('Database error');
      mockRejectedValue(mockFindUser, error);

      // Act
      const response = await request(app).get('/users/123');

      // Assert
      expect(response.status).toBe(500);
      expect(response.body).toEqual({ error: 'Internal server error' });
    });
  });

  // ============================================================================
  // Example 6: Using custom matchers
  // ============================================================================

  describe('Custom Matchers', () => {
    it('should validate dates', () => {
      const validDate = new Date();
      const invalidDate = new Date('invalid');

      expect(validDate).toBeValidDate();
      expect(invalidDate).not.toBeValidDate();
    });

    it('should validate UUIDs', () => {
      const validUUID = '123e4567-e89b-12d3-a456-426614174000';
      const invalidUUID = 'not-a-uuid';

      expect(validUUID).toBeValidUUID();
      expect(invalidUUID).not.toBeValidUUID();
    });

    it('should validate JWTs', () => {
      const validJWT = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIn0.dozjgNryP4J3jVmNHl0w5N_XgL0n3I9PlFUP0THsR8U';
      const invalidJWT = 'not-a-jwt';

      expect(validJWT).toBeValidJWT();
      expect(invalidJWT).not.toBeValidJWT();
    });

    it('should match partial call arguments', () => {
      const mockFn = jest.fn();
      mockFn({ userId: '123', name: 'Test', extra: 'data' });

      expect(mockFn).toHaveBeenCalledWithMatch({ userId: '123' });
    });
  });

  // ============================================================================
  // Example 7: Testing concurrent operations
  // ============================================================================

  describe('Concurrent Operations', () => {
    beforeEach(() => {
      jest.clearAllMocks();
    });

    it('should handle multiple simultaneous requests', async () => {
      // Arrange
      const users = [
        createMockUser({ id: '1', email: 'user1@example.com' }),
        createMockUser({ id: '2', email: 'user2@example.com' }),
        createMockUser({ id: '3', email: 'user3@example.com' }),
      ];

      mockFindUser
        .mockResolvedValueOnce(users[0])
        .mockResolvedValueOnce(users[1])
        .mockResolvedValueOnce(users[2]);

      // Act
      const results = await Promise.all([
        findUser('1'),
        findUser('2'),
        findUser('3'),
      ]);

      // Assert
      expect(results).toEqual(users);
      expect(mockFindUser).toHaveBeenCalledTimes(3);
    });

    it('should handle partial failures', async () => {
      // Arrange
      const user = createMockUser({ id: '1' });
      const error = new Error('User 2 not found');

      mockFindUser
        .mockResolvedValueOnce(user)
        .mockRejectedValueOnce(error)
        .mockResolvedValueOnce(user);

      // Act
      const results = await Promise.allSettled([
        findUser('1'),
        findUser('2'),
        findUser('3'),
      ]);

      // Assert
      expect(results[0].status).toBe('fulfilled');
      expect(results[1].status).toBe('rejected');
      expect(results[2].status).toBe('fulfilled');
      expect(mockFindUser).toHaveBeenCalledTimes(3);
    });
  });
});
